"""Build a standalone rescue updater from the shipped transport/install code.
The helper installs to ActiveScriptPath and leaves launching Studio to the user.
"""
from pathlib import Path
root=Path(__file__).resolve().parents[1]
s=(root/'Composition Studio.lua').read_text()
def section(a,b):return s[s.index(a):s.index(b)]
header='''-- @description Composition Studio: einmaliger Updater ohne Studio-Menü
-- @version 1.0.0
-- Generated by tools/build_update_helper.py. Does not require ReaImGui.
local SCRIPT_NAME="Composition Studio"
local EXT_SECTION="CompositionStudio"
local WINDOW_STATE_KEY="WindowOpen"
local SCRIPT_PATH=reaper.GetExtState(EXT_SECTION,"ActiveScriptPath")
local function message(text) reaper.ShowMessageBox(text,SCRIPT_NAME.." – Update",0) end
local f=SCRIPT_PATH~="" and io.open(SCRIPT_PATH,"rb") or nil
local installed=f and f:read("*a") or nil;if f then f:close() end
if not installed or not installed:find('local SCRIPT_NAME="Composition Studio"',1,true) then
 message("Die registrierte Studio-Datei wurde nicht gefunden. Bitte Composition Studio einmal starten und wieder schließen.");return
end
local VERSION=installed:match("%-%- @version%s+([%w%.%-]+)") or "0.0.0"
local UPDATE_URL="https://raw.githubusercontent.com/wibem1/Composition-Studio/main/Composition%20Studio.lua"
local open,busy,restarting=true,false,false
local update_status="Update wird vorbereitet …"
local function trim(s)return (s or ""):gsub("^%s+",""):gsub("%s+$","")end
'''
transport=section('local IS_WINDOWS=','local function json_escape(s)')
update=section('local function read_file(p)','local function utf8(cp)')
a=update.index(' update_status="Update auf "..rv.." installiert. Neustart …"')
b=update.index('\nlocal function poll_update()',a)
update=update[:a]+''' update_status="Version "..rv.." wurde installiert. Bitte Composition Studio erneut öffnen."
 busy=false
 reaper.SetExtState(EXT_SECTION,WINDOW_STATE_KEY,"0",true)
end
''' +update[b:]
tail='''
gfx.init("Composition Studio aktualisieren",440,90)
install_update()
local function tick()
 if not busy then gfx.quit();return end
 if gfx.getchar()<0 then
  gfx.quit();message("Update abgebrochen. Die Studio-Datei wurde nicht verändert.");return
 end
 gfx.set(0.12,0.12,0.12,1);gfx.rect(0,0,gfx.w,gfx.h,1)
 gfx.set(1,1,1,1);gfx.x=14;gfx.y=16;gfx.drawstr(update_status)
 gfx.y=45;gfx.x=14;gfx.drawstr("Download und Datei werden vor der Installation geprüft.")
 gfx.update()
 poll_update()
 if busy then reaper.defer(tick) else gfx.quit() end
end
tick()
'''
(root/'Composition-Studio-Update.lua').write_text(header+transport+update+tail)
print('Built Composition-Studio-Update.lua from current update transport and installer')
